+           &hf_opus_frame_count_m};

     col_set_str(pinfo->cinfo, COL_PROTOCOL, "OPUS");

@@ -128,14 +186,7 @@ dissect_opus(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void* data _U_
